package com.bank.statement;

import java.util.*;
import java.util.logging.*;

public class ImmutableLeakDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // --- BROKEN: not truly immutable ---
        List<String> entries = new ArrayList<>(List.of("SAV2001 debit 50000"));
        LeakyStatement leaky = new LeakyStatement("SAV2001", entries);

        entries.add("FAKE via constructor leak");            // mutate caller's list
        leaky.getEntries().add("FAKE via getter leak");      // mutate internal list
        log.severe(() -> "LEAKY statement corrupted: " + leaky.getEntries());

        // --- FIXED: truly immutable ---
        List<String> entries2 = new ArrayList<>(List.of("SAV2001 debit 50000"));
        SafeStatement safe = new SafeStatement("SAV2001", entries2);

        entries2.add("FAKE via constructor");                // no effect (copied in)
        try {
            safe.getEntries().add("FAKE via getter");        // blocked (unmodifiable out)
        } catch (UnsupportedOperationException e) {
            log.info("SAFE statement: getter tamper blocked");
        }
        log.info(() -> "SAFE statement intact: " + safe.getEntries());
    }
}

// ─── Would be LeakyStatement.java in a real project (BROKEN) ───
final class LeakyStatement {
    private final String accountId;
    private final List<String> entries; // final ref, but mutable contents
    LeakyStatement(String accountId, List<String> entries) {
        this.accountId = accountId;
        this.entries = entries;          // LEAK 1: stores caller's reference
    }
    List<String> getEntries() { return entries; } // LEAK 2: returns internal reference
}

// ─── Would be SafeStatement.java in a real project (FIXED) ───
final class SafeStatement {
    private final String accountId;
    private final List<String> entries;
    SafeStatement(String accountId, List<String> entries) {
        this.accountId = accountId;
        this.entries = new ArrayList<>(entries); // FIX 1: defensive copy IN
    }
    // FIX 2: unmodifiable view OUT (or return new ArrayList<>(entries))
    List<String> getEntries() { return Collections.unmodifiableList(entries); }
}
